/* Place commentary for the 41 reference places that were showing only the OpenBible source line.
   Written for JudeBible from the scripture passages named in each entry (no commentary text copied). Locations: OpenBible.info (CC BY 4.0). Not reviewed by a scholar. */
window.JBC_PLACE_COMMENTARY = {"cana":{"hook":"갈릴리의 작은 마을로, 예수께서 첫 표적으로 물을 포도주로 바꾸신 곳입니다.","place":"갈릴리 아랫지방, 나사렛 북쪽으로 추정됩니다. 후보지가 키르벳 카나와 카프르 칸나 등으로 나뉘어 확정되지 않았습니다.","meaning":null,"paras":["요한복음 2:1–11은 가나의 혼인 잔치에서 포도주가 떨어지자 예수께서 돌 항아리 여섯 개의 물을 포도주로 바꾸신 일을 기록하고, 이를 “표적의 처음”이라 부릅니다(2:11). 요한복음은 이 표적으로 제자들이 예수를 믿었다고 적습니다.","예수께서는 뒤에 다시 가나에 가셔서 가버나움에서 온 왕의 신하의 아들을 멀리서 고치십니다(요 4:46–54). 나다나엘도 “갈릴리 가나” 사람으로 소개됩니다(요 21:2)."],"read":[{"ref":"요 2:1","hash":"jhn-2:1","why":"첫 표적 기사 전문."},{"ref":"요 4:46","hash":"jhn-4:46","why":"가나에서 하신 두 번째 표적."},{"ref":"요 21:2","hash":"jhn-21:2","why":"나다나엘의 고향."}]},"nazareth":{"hook":"예수께서 자라신 갈릴리의 작은 마을입니다. 구약에는 나오지 않습니다.","place":"갈릴리 아랫지방의 산지 마을로, 이스르엘 골짜기를 내려다보는 언덕 위에 있었습니다.","meaning":null,"paras":["누가복음 1:26–38에서 천사가 나사렛의 마리아에게 나타나 예수의 잉태를 알립니다. 요셉과 마리아는 헤롯 뒤에 이집트에서 돌아와 나사렛에 정착하고(마 2:23; 눅 2:39), 예수는 그곳에서 자라셨습니다(눅 2:51–52).","누가복음 4:16–30에서 예수께서 나사렛 회당에서 이사야서를 읽고 “오늘 이 글이 너희 귀에 응하였느니라”고 하시자 사람들이 처음엔 놀라다가 곧 분노하여 예수를 성 밖으로 몰아냅니다. 요한복음 1:46의 “나사렛에서 무슨 선한 것이 날 수 있느냐”는 말은 이 마을이 작고 보잘것없게 여겨졌음을 보여 줍니다."],"read":[{"ref":"눅 1:26","hash":"luk-1:26","why":"마리아에게 알림."},{"ref":"눅 4:16","hash":"luk-4:16","why":"나사렛 회당에서의 설교와 배척."},{"ref":"요 1:46","hash":"jhn-1:46","why":"나다나엘의 말."}]},"bethlehem":{"hook":"다윗의 고향이며 예수께서 나신 유다의 작은 성읍입니다.","place":"예루살렘 남쪽 약 9km, 유다 산지에 있습니다.","meaning":"“떡집”(‘벧’=집, ‘레헴’=떡)으로 풀이됩니다.","paras":["룻기의 무대이자 다윗이 태어나고 사무엘에게 기름 부음을 받은 곳입니다(삼상 16:1–13). 미가 5:2는 “베들레헴 에브라다야 … 네게서 내게로 나올 것이라 그는 이스라엘 중에 치리자가 될 자”라고 예언합니다.","누가복음 2:1–20은 로마 황제의 호적 령으로 요셉과 마리아가 베들레헴으로 가서 예수께서 나시고, 목자들이 천사의 소식을 듣고 찾아오는 이야기를 전합니다. 마태복음 2:1–12는 동방에서 온 박사들이 이곳에서 예수께 경배하는 장면을 기록합니다."],"read":[{"ref":"미 5:2","hash":"mic-5:2","why":"베들레헴에서 나올 통치자의 예언."},{"ref":"삼상 16:1","hash":"1sa-16:1","why":"다윗의 기름 부음."},{"ref":"눅 2:4","hash":"luk-2:4","why":"요셉과 마리아가 베들레헴으로 감."},{"ref":"마 2:1","hash":"mat-2:1","why":"동방 박사의 방문."}]},"jerusalem":{"hook":"성전이 있던 이스라엘의 중심 성읍이며, 예수께서 수난을 겪으시고 초대교회가 시작된 곳입니다.","place":"유대 산지 위에 있으며 기드론 골짜기를 사이에 두고 올리브 산과 마주합니다.","meaning":null,"paras":["구약에서 다윗이 이 성을 차지해 도성으로 삼았고(삼하 5:6–9), 솔로몬이 성전을 세웠으며(왕상 6장), 바벨론이 성과 성전을 무너뜨렸습니다(왕하 25장). 귀환한 백성은 느헤미야 때 성벽을 다시 쌓았습니다(느 6:15).","신약에서 예수께서는 어려서 성전에 봉헌되고(눅 2:22–38) 열두 살에 성전에서 선생들과 문답하셨으며(눅 2:41–52), 마지막 한 주간(마 21–28장)에 입성, 성전 정화, 가르치심, 최후의 만찬, 재판, 십자가, 부활을 이곳에서 겪으십니다. 오순절에 성령이 임한 곳도 예루살렘이고(행 2장), 이방인 신자의 문제를 논의한 예루살렘 회의도 이곳에서 열렸습니다(행 15장)."],"read":[{"ref":"삼하 5:6","hash":"2sa-5:6","why":"다윗이 예루살렘을 차지함."},{"ref":"왕상 6:1","hash":"1ki-6:1","why":"솔로몬의 성전 건축."},{"ref":"눅 19:41","hash":"luk-19:41","why":"예수께서 성을 보고 우심."},{"ref":"행 2:1","hash":"act-2:1","why":"오순절 성령 강림."}]},"bethany":{"hook":"올리브 산 동남쪽 기슭의 마을로, 나사로와 마르다·마리아가 살던 곳입니다.","place":"예루살렘 동쪽 약 3km(요 11:18은 “십오 스타디온”)에 있었습니다.","meaning":null,"paras":["요한복음 11장에서 예수께서 죽은 지 나흘 된 나사로를 살리십니다. 누가복음 10:38–42는 마르다가 예수를 영접하고 마리아가 발치에 앉아 말씀을 듣는 장면을 전합니다.","마가복음 14:3–9와 요한복음 12:1–8은 예수께서 베다니에서 향유 부음을 받으신 일을 기록합니다. 예수께서는 마지막 한 주간 동안 베다니에서 머무르시며 예루살렘을 오가셨고(막 11:11), 누가복음 24:50은 베다니 근처에서 승천하셨다고 전합니다."],"read":[{"ref":"요 11:1","hash":"jhn-11:1","why":"나사로가 살아남."},{"ref":"눅 10:38","hash":"luk-10:38","why":"마르다와 마리아."},{"ref":"막 14:3","hash":"mrk-14:3","why":"향유를 부은 여인."},{"ref":"눅 24:50","hash":"luk-24:50","why":"베다니 앞에서의 승천."}]},"gethsemane":{"hook":"올리브 산 기슭의 동산으로, 예수께서 잡히시기 전날 밤 기도하신 곳입니다.","place":"예루살렘 동쪽 기드론 골짜기 건너편, 올리브 산 서쪽 기슭으로 전해집니다.","meaning":"“기름 짜는 틀”로 풀이됩니다.","paras":["마태복음 26:36–46과 마가복음 14:32–42는 예수께서 제자들을 두고 홀로 기도하시며 “아버지여 … 이 잔을 내게서 지나가게 하옵소서 그러나 내 원대로 마시옵고 아버지의 원대로 되기를 원하나이다”라고 하신 일을 전합니다. 누가복음 22:44는 땀이 핏방울처럼 되었다고 기록합니다.","요한복음 18:1–11에서는 예수께서 기드론 시내 건너 동산에 들어가시고, 유다가 군대와 함께 와서 예수를 체포합니다. 이 동산의 이름 ‘겟세마네’는 히브리어 ‘기름 짜는 틀’에서 온 것으로 풀이됩니다."],"read":[{"ref":"마 26:36","hash":"mat-26:36","why":"겟세마네의 기도."},{"ref":"눅 22:39","hash":"luk-22:39","why":"올리브 산에서의 기도."},{"ref":"요 18:1","hash":"jhn-18:1","why":"체포 장면."}]},"golgotha":{"hook":"예수께서 십자가에 달리신 곳으로, “해골의 곳”이라는 뜻입니다.","place":"당시 예루살렘 성벽 밖 가까운 곳(요 19:20; 히 13:12)입니다. 전통적으로 성묘교회 자리로 전하며, 정확한 위치는 확정되지 않았습니다.","meaning":"“해골의 곳”(막 15:22)이라는 뜻입니다.","paras":["네 복음서는 모두 예수께서 골고다에서 십자가에 못 박히셨다고 전합니다(마 27:33–50; 막 15:22–37; 눅 23:33–46; 요 19:17–30). 마가복음 15:22는 골고다를 “해골의 곳”이라 번역하며, 누가복음 23:33은 “해골”이라 부릅니다.","요한복음 19:41–42는 그곳에 동산이 있었고 그 안에 아직 사람을 장사한 일이 없는 새 무덤이 있어 예수를 그곳에 모셨다고 적습니다. 히브리서 13:12는 예수께서 “성문 밖에서” 고난을 받으셨다고 말합니다."],"read":[{"ref":"마 27:33","hash":"mat-27:33","why":"골고다에 이름."},{"ref":"요 19:17","hash":"jhn-19:17","why":"골고다로 나가심."},{"ref":"히 13:12","hash":"heb-13:12","why":"성문 밖에서의 고난."}]},"jericho":{"hook":"요단 골짜기의 오아시스 성읍으로, 가나안 정복의 첫 성이며 신약에서는 삭개오 이야기의 무대입니다.","place":"사해 북쪽 요단 서편에 있습니다. 구약 여리고(텔 에스술탄)와 신약 시대의 여리고(헤롯의 겨울 궁전이 있던 남쪽의 유적)는 위치가 다릅니다.","meaning":null,"paras":["여호수아 6장에서 이스라엘이 여리고 성을 도는 이야기가 나옵니다. 여리고는 “종려나무 성읍”으로도 불렸고(삿 3:13), 엘리야와 엘리사 시대에도 선지자들의 공동체가 있었습니다(왕하 2:4–18).","누가복음 10:30의 강도 만난 사람은 예루살렘에서 여리고로 내려가던 길에서 일을 당합니다. 누가복음 18:35–43은 여리고 가까이에서 맹인을 고치신 일을, 19:1–10은 세리장 삭개오를 만나 “오늘 구원이 이 집에 이르렀으니”라고 하신 일을 전합니다."],"read":[{"ref":"수 6:1","hash":"jos-6:1","why":"여리고 성 이야기."},{"ref":"눅 18:35","hash":"luk-18:35","why":"맹인을 고치심."},{"ref":"눅 19:1","hash":"luk-19:1","why":"삭개오."}]},"bethsaida":{"hook":"갈릴리 바다 북동쪽의 어촌으로, 빌립·안드레·베드로의 고향입니다.","place":"요단 강이 갈릴리 바다로 들어가는 곳 가까이로 보며, 엣텔 등 후보지 사이에 논란이 있어 위치가 확정되지 않았습니다.","meaning":null,"paras":["요한복음 1:44는 빌립과 안드레와 베드로가 벳새다 사람이라고 적습니다. 마태복음 11:21은 예수께서 고라신과 함께 벳새다를 책망하시며 능력이 있었으나 회개하지 않은 성읍으로 말씀하십니다.","마가복음 8:22–26은 벳새다에서 맹인을 두 번에 걸쳐 고치신 일을, 누가복음 9:10–17은 벳새다라 하는 고을 가까운 곳에서 오천 명을 먹이신 일을 전합니다(복음서 사이에 장소 표기가 조금씩 다릅니다)."],"read":[{"ref":"요 1:44","hash":"jhn-1:44","why":"제자들의 고향."},{"ref":"막 8:22","hash":"mrk-8:22","why":"맹인을 고치심."},{"ref":"눅 9:10","hash":"luk-9:10","why":"오병이어 장면의 장소."},{"ref":"마 11:21","hash":"mat-11:21","why":"벳새다에 대한 책망."}]},"caesarea_philippi":{"hook":"헤르몬 산 기슭의 성읍으로, 베드로가 예수를 그리스도라 고백한 곳입니다.","place":"갈릴리 북쪽 헤르몬 산 남쪽 기슭에 있습니다(옛 이름 파네아스).","meaning":null,"paras":["마태복음 16:13–20은 예수께서 “사람들이 인자를 누구라 하느냐”고 물으시고 베드로가 “주는 그리스도시요 살아 계신 하나님의 아들이시니이다”라고 고백하는 장면을 가이사랴 빌립보 지방에서 전합니다(막 8:27–30).","이 성은 분봉왕 빌립이 로마 황제 가이사를 기리고 자신의 이름을 붙여 ‘가이사랴 빌립보’라 불렀고, 해안의 가이사랴와 구분됩니다. 이 고백 이후 예수께서는 처음으로 십자가의 길을 제자들에게 말씀하기 시작하십니다(마 16:21)."],"read":[{"ref":"마 16:13","hash":"mat-16:13","why":"베드로의 고백."},{"ref":"막 8:27","hash":"mrk-8:27","why":"같은 사건의 마가 기록."},{"ref":"눅 9:18","hash":"luk-9:18","why":"누가의 기록."}]},"sidon":{"hook":"지중해 연안의 오랜 페니키아 항구 도시입니다.","place":"레바논 남부 해안, 두로 북쪽에 있습니다.","meaning":null,"paras":["창세기 10:15는 시돈을 가나안의 맏아들로 적고, 여호수아 19:28은 아셀 지파 경계 근처에 시돈이 있었다고 합니다. 이스라엘 북쪽의 이웃으로 자주 등장합니다.","신약에서는 마태복음 15:21–28의 가나안 여인 이야기가 “두로와 시돈 지방”에서 일어나고(막 7:24, 31), 누가복음 6:17은 두로와 시돈 해안에서 사람들이 예수께 나아왔다고 전합니다. 사도행전 27:3에서는 바울이 로마로 가는 길에 시돈에 배가 닿아 친구들을 만나는 것이 허락됩니다."],"read":[{"ref":"창 10:15","hash":"gen-10:15","why":"시돈의 계보."},{"ref":"막 7:24","hash":"mrk-7:24","why":"두로와 시돈 지방."},{"ref":"행 27:3","hash":"act-27:3","why":"바울이 시돈에 닿음."}]},"tyre":{"hook":"지중해 연안의 페니키아 항구 도시로, 솔로몬 시대부터 이스라엘과 교류가 깊었습니다.","place":"레바논 남부 해안, 갈릴리 북서쪽에 있습니다.","meaning":"“바위”(히브리어 ‘초르’)에서 온 이름으로 풀이됩니다.","paras":["두로 왕 히람은 다윗과 솔로몬의 성전·궁전 건축을 돕고 백향목을 보냈습니다(왕상 5장). 선지자 에스겔은 두로의 교만과 몰락을 길게 말합니다(겔 26–28장).","예수께서는 고라신과 벳새다를 책망하시며 “두로와 시돈이 너희보다 견디기 쉬우리라”고 하십니다(마 11:21–22). 사도행전 21:3–6에서 바울은 3차 선교여행을 마치고 예루살렘으로 가는 길에 두로에서 이레를 머물고, 제자들이 그에게 눈물로 작별합니다."],"read":[{"ref":"왕상 5:1","hash":"1ki-5:1","why":"히람과 솔로몬."},{"ref":"겔 26:1","hash":"ezk-26:1","why":"두로에 대한 예언."},{"ref":"행 21:3","hash":"act-21:3","why":"바울이 두로에서 머묾."}]},"samaria":{"hook":"북이스라엘의 수도였던 성읍이며, 성읍과 그 주변 지역을 함께 가리키는 이름입니다.","place":"에브라임 산지 북쪽, 세겜 북서쪽의 언덕에 있습니다.","meaning":"오므리가 산 주인 “세멜”의 이름을 따라 지었다고 합니다(왕상 16:24).","paras":["열왕기상 16:24에서 오므리가 세멜에게서 산을 사서 성을 쌓고 그 산 주인의 이름을 따라 사마리아라 불렀습니다. 이후 북이스라엘의 도성이 되었고, 앗수르가 포위해 BC 722년경 함락시켰습니다(왕하 17:5–6).","신약에서는 요한복음 4장에서 예수께서 사마리아를 지나시다 수가의 우물가에서 사마리아 여인을 만나십니다. 사도행전 8:5–25에서는 빌립이 사마리아 성에 내려가 복음을 전하고, 베드로와 요한이 보내져 성령이 임합니다."],"read":[{"ref":"왕상 16:24","hash":"1ki-16:24","why":"사마리아의 건설."},{"ref":"요 4:4","hash":"jhn-4:4","why":"사마리아를 지나심."},{"ref":"행 8:5","hash":"act-8:5","why":"빌립의 전도."}]},"gaza":{"hook":"지중해 연안의 블레셋 성읍입니다. 신약에서는 빌립이 에디오피아 내시를 만난 길의 도착지입니다.","place":"지중해 연안 남쪽 해안 평야에 있습니다.","meaning":null,"paras":["가사는 블레셋의 다섯 도시 중 하나로, 삼손이 이곳에서 눈이 뽑히고 맷돌을 돌리다 마지막 힘을 내어 성전 기둥을 무너뜨립니다(삿 16:1–3, 21–30).","사도행전 8:26은 주의 사자가 빌립에게 “예루살렘에서 가사로 내려가는 길 곧 광야로 가라”고 하시고, 빌립은 그 길에서 이사야서를 읽던 에디오피아 여왕의 내시를 만나 세례를 줍니다(행 8:26–40)."],"read":[{"ref":"삿 16:1","hash":"jdg-16:1","why":"삼손과 가사."},{"ref":"행 8:26","hash":"act-8:26","why":"가사로 내려가는 길."}]},"caesarea":{"hook":"헤롯 대왕이 세운 지중해 해안의 로마 총독 도시로, 고넬료와 바울의 구금 이야기의 무대입니다.","place":"지중해 연안 샤론 평야, 오늘의 이스라엘 해안에 있습니다. 가이사랴 빌립보와는 다른 곳입니다.","meaning":"로마 황제 가이사를 기려 붙인 이름입니다.","paras":["이 항구 도시는 헤롯 대왕이 로마 황제 가이사 아구스도를 기려 대규모로 세웠고, 유대 총독의 관저가 있었습니다. 사도행전 8:40에서 빌립이 이곳에 이르고, 10장에서는 이탈리아 부대 백부장 고넬료가 베드로를 청해 이방인이 처음으로 성령을 받습니다(행 10:44–48).","바울은 3차 선교여행 후 빌립의 집에 머물고(행 21:8), 체포된 뒤 가이사랴에서 약 2년 동안 구금되어 벨릭스, 베스도, 아그립바 앞에서 변론하다 가이사에게 상소합니다(행 23:23–26:32, 24:27)."],"read":[{"ref":"행 10:1","hash":"act-10:1","why":"고넬료."},{"ref":"행 21:8","hash":"act-21:8","why":"빌립의 집."},{"ref":"행 24:27","hash":"act-24:27","why":"2년의 구금."}]},"antioch":{"hook":"시리아의 큰 도시로, 처음 “그리스도인”이라 불린 사람들의 교회와 바울의 선교 파송지입니다.","place":"오론테스 강 가, 오늘날 튀르키예 남부 안타키아에 있었습니다. 로마 제국에서 손꼽히는 큰 도시였습니다.","meaning":"셀레우코스 1세가 아버지 안티오코스의 이름을 따라 세운 도시입니다.","paras":["사도행전 11:19–26은 스데반의 일로 흩어진 사람들이 안디옥에서 헬라인에게도 복음을 전하고, 바나바가 사울을 데려와 일 년 동안 가르치며, 거기서 제자들이 처음으로 “그리스도인”이라 불렸다고 전합니다.","13:1–3에서 안디옥 교회가 금식하고 기도할 때 성령께서 바나바와 사울을 따로 세우라고 하시고, 이로써 1차 선교여행이 시작됩니다. 안디옥은 세 차례 선교여행의 출발·귀환지이기도 합니다. 갈라디아서 2:11–14는 안디옥에서 일어난 베드로와 바울의 충돌을 전합니다."],"read":[{"ref":"행 11:19","hash":"act-11:19","why":"안디옥 교회의 시작."},{"ref":"행 13:1","hash":"act-13:1","why":"선교사 파송."},{"ref":"갈 2:11","hash":"gal-2:11","why":"베드로와 바울."}]},"damascus":{"hook":"시리아의 오랜 도시로, 바울이 부활하신 주를 만나 회심한 길의 목적지입니다.","place":"시리아 남서부, 헤르몬 산 동쪽의 오아시스 평야에 있습니다.","meaning":null,"paras":["구약에서 다메섹은 아람의 중심으로 이스라엘과 자주 맞섭니다(왕상 11:23–25). 나아만 장군의 이야기에서 아바나와 바르발 강이 언급되는데(왕하 5:12), 다메섹의 강들입니다.","사도행전 9:1–19에서 사울은 다메섹의 그리스도인들을 잡으려 가다가 하늘의 빛과 예수의 음성을 만나 눈이 멀고, 다메섹에서 아나니아의 안수로 보게 되어 세례를 받습니다. 이후 사울은 회당에서 예수가 하나님의 아들이심을 전하다 위협을 받아, 광주리를 타고 성벽으로 내려 도망합니다(행 9:23–25; 고후 11:32–33)."],"read":[{"ref":"행 9:1","hash":"act-9:1","why":"사울의 회심."},{"ref":"고후 11:32","hash":"2co-11:32","why":"광주리로 성벽을 내려감."},{"ref":"갈 1:17","hash":"gal-1:17","why":"아라비아에 갔다가 다메섹으로 돌아옴."}]},"paphos":{"hook":"구브로 섬의 서쪽 도시로, 1차 선교여행에서 총독 서기오 바울을 만난 곳입니다.","place":"지중해 구브로(키프로스) 섬 서남쪽 해안에 있습니다.","meaning":null,"paras":["바울과 바나바는 살라미에서 섬을 가로질러 바보에 이르러 박수 바예수(엘루마)를 만나는데, 엘루마가 총독 서기오 바울이 믿는 것을 막으려 하자 바울이 성령 충만하여 책망하고 그가 얼마 동안 눈이 멀게 됩니다(행 13:6–11).","총독은 이 일을 보고 믿으며 주의 가르침에 놀랍니다(행 13:12). 사도행전은 이 즈음부터 ‘사울’ 대신 ‘바울’을 쓰기 시작하며(13:9), 이야기의 중심이 바울에게로 옮겨 갑니다. 바울 일행은 이곳에서 배를 타고 소아시아 버가로 향합니다(13:13)."],"read":[{"ref":"행 13:6","hash":"act-13:6","why":"바보에서의 사건."},{"ref":"행 13:13","hash":"act-13:13","why":"버가로 건너감."}]},"salamis":{"hook":"구브로 섬 동쪽의 큰 항구로, 1차 선교여행에서 처음 말씀을 전한 곳입니다.","place":"구브로(키프로스) 섬 동쪽 해안에 있으며 안디옥에서 배로 닿기 좋은 항구였습니다.","meaning":null,"paras":["안디옥을 떠난 바울과 바나바는 실루기아에서 배로 구브로에 이르러 살라미에서 유대인의 여러 회당에 하나님의 말씀을 전합니다. 요한(마가)이 수종자로 함께 있었습니다(행 13:4–5).","구브로는 바나바의 고향입니다(행 4:36). 2차 선교여행 직전 바울과 바나바가 갈라선 뒤, 바나바는 마가를 데리고 구브로로 갑니다(행 15:39)."],"read":[{"ref":"행 13:4","hash":"act-13:4","why":"살라미 전도."},{"ref":"행 4:36","hash":"act-4:36","why":"구브로 사람 바나바."},{"ref":"행 15:39","hash":"act-15:39","why":"바나바와 마가의 구브로행."}]},"perga":{"hook":"소아시아 남부 밤빌리아의 도시로, 1차 선교여행 중 마가가 일행을 떠난 곳입니다.","place":"오늘날 튀르키예 남부 지중해 연안 안쪽에 있었습니다.","meaning":null,"paras":["바울 일행은 바보에서 배를 타고 밤빌리아 버가에 이릅니다. 이곳에서 요한(마가)이 일행을 떠나 예루살렘으로 돌아가고(행 13:13), 이 일은 뒤에 바울과 바나바가 갈라서는 이유가 됩니다(행 15:37–39).","돌아오는 길에 두 사람은 다시 버가에서 말씀을 전하고 앗달리아에서 배로 안디옥에 돌아갑니다(행 14:25–26)."],"read":[{"ref":"행 13:13","hash":"act-13:13","why":"요한이 떠남."},{"ref":"행 14:25","hash":"act-14:25","why":"귀로에서 말씀을 전함."},{"ref":"행 15:37","hash":"act-15:37","why":"마가 문제."}]},"antioch_pisidia":{"hook":"소아시아 비시디아 지방의 안디옥으로, 바울이 첫 회당 설교를 한 곳입니다.","place":"오늘날 튀르키예 내륙의 고원 지대에 있었으며, 시리아의 안디옥과는 다른 도시입니다.","meaning":null,"paras":["사도행전 13:14–41에서 바울은 안식일에 회당에서 이스라엘 역사를 짚으며 예수가 약속된 구주이심을 설교합니다. 이튿날 안식일에는 온 성이 거의 모였고, 일부 유대인이 시기하여 반대하자 바울과 바나바는 “우리가 이방인에게로 향하노라”고 선언합니다(13:44–47).","이방인들이 기뻐하며 주의 말씀이 그 지역에 퍼졌으나, 유대인들이 사람들을 선동해 바울과 바나바를 지경에서 쫓아냅니다(13:49–50). 두 사람은 발의 티끌을 떨고 이고니온으로 갑니다."],"read":[{"ref":"행 13:14","hash":"act-13:14","why":"회당 설교."},{"ref":"행 13:46","hash":"act-13:46","why":"이방인에게로."},{"ref":"딤후 3:11","hash":"2ti-3:11","why":"안디옥·이고니온·루스드라의 박해."}]},"iconium":{"hook":"소아시아 내륙의 도시로, 1차 선교여행에서 많은 유대인과 헬라인이 믿은 곳입니다.","place":"오늘날 튀르키예 코니아에 해당하며, 내륙 고원의 큰 성읍이었습니다.","meaning":null,"paras":["바울과 바나바는 이고니온 회당에서 말씀을 전했고 유대인과 헬라인 가운데 허다한 무리가 믿습니다. 그러나 믿지 않는 유대인들이 이방인들을 선동하여 형제들을 해치려 하자 두 사도는 오래 머물며 담대히 전하다가 돌로 치려는 계획을 알고 루스드라와 더베로 피합니다(행 14:1–6).","비시디아 안디옥과 이고니온의 유대인들은 뒤에 루스드라까지 와서 무리를 선동하여 바울을 돌로 칩니다(행 14:19). 디모데는 루스드라와 이고니온에서 칭찬받는 사람이었습니다(행 16:1–2)."],"read":[{"ref":"행 14:1","hash":"act-14:1","why":"이고니온에서의 전도."},{"ref":"행 14:19","hash":"act-14:19","why":"유대인들의 추적."},{"ref":"딤후 3:11","hash":"2ti-3:11","why":"이고니온의 박해."}]},"lystra":{"hook":"소아시아 루가오니아의 도시로, 바울이 앉은뱅이를 고치고 돌에 맞은 곳이며 디모데의 고향입니다.","place":"이고니온 남서쪽 약 40km 부근, 오늘날 튀르키예 내륙에 있었습니다.","meaning":null,"paras":["사도행전 14:8–18은 나면서 걷지 못하던 사람을 바울이 고치자 무리가 바나바를 제우스, 바울을 헤르메스라 부르며 제사하려 한 일을 전합니다. 두 사도는 옷을 찢으며 말리고 살아 계신 하나님께 돌아오라고 말합니다.","그 후 유대인들이 와서 무리를 설득하자 바울은 돌에 맞아 성 밖으로 끌려 나가지만 다시 일어나 성에 들어갑니다(14:19–20). 사도행전 16:1–3은 바울이 2차 여행에서 이곳을 다시 찾아 디모데를 동행하게 하는 장면입니다."],"read":[{"ref":"행 14:8","hash":"act-14:8","why":"앉은뱅이를 고침."},{"ref":"행 14:19","hash":"act-14:19","why":"돌에 맞음."},{"ref":"행 16:1","hash":"act-16:1","why":"디모데를 만남."}]},"derbe":{"hook":"소아시아 루가오니아의 성읍으로, 1차 선교여행의 가장 먼 지점입니다.","place":"루스드라 동쪽, 오늘날 튀르키예 중남부의 내륙에 있었으며 위치는 학자들이 대체로 정했지만 확정은 아닙니다.","meaning":null,"paras":["루스드라에서 돌에 맞은 바울은 이튿날 바나바와 더베로 가서 복음을 전하여 많은 제자를 삼습니다(행 14:20–21). 이 선교여행은 더베를 가장 멀리 두고 그 길을 되돌아 루스드라, 이고니온, 비시디아 안디옥을 다시 거쳐 안디옥으로 돌아옵니다.","더베 사람 가이오는 바울 일행의 한 사람으로 이름이 나오고(행 20:4), 2차 선교여행에서도 바울은 더베와 루스드라를 다시 찾습니다(행 16:1)."],"read":[{"ref":"행 14:20","hash":"act-14:20","why":"더베 전도."},{"ref":"행 16:1","hash":"act-16:1","why":"더베와 루스드라 재방문."},{"ref":"행 20:4","hash":"act-20:4","why":"더베 사람 가이오."}]},"troas":{"hook":"에게 해 연안의 항구로, 바울이 마게도냐 사람의 환상을 본 곳입니다.","place":"소아시아 북서쪽 해안, 옛 트로이 근처에 있었습니다.","meaning":null,"paras":["사도행전 16:6–10에서 바울 일행은 성령께서 아시아와 비두니아로 가는 길을 막으시자 무시아를 지나 드로아로 내려옵니다. 거기서 밤에 한 마게도냐 사람이 “건너와서 우리를 도우라”고 청하는 환상을 보고, 곧 마게도냐로 건너갑니다. 이 대목부터 “우리”가 나옵니다.","3차 선교여행 막바지에는 드로아에서 이레를 머물며 주간의 첫날 모여 떡을 떼고, 창에서 떨어져 죽은 유두고를 바울이 살립니다(행 20:6–12). 고린도후서 2:12와 디모데후서 4:13도 드로아를 언급합니다."],"read":[{"ref":"행 16:8","hash":"act-16:8","why":"마게도냐 환상."},{"ref":"행 20:6","hash":"act-20:6","why":"드로아에서의 이레."},{"ref":"딤후 4:13","hash":"2ti-4:13","why":"드로아에 둔 겉옷."}]},"philippi":{"hook":"마게도냐의 로마 식민 도시로, 바울이 유럽에서 처음 교회를 세운 곳입니다.","place":"에게 해 북쪽, 마게도냐 동부에 있었으며 에그나티아 대로가 지나갔습니다.","meaning":"마게도냐의 필립 2세의 이름에서 온 도시 이름입니다.","paras":["사도행전 16:11–15에서 바울은 안식일에 성문 밖 강가에서 기도하러 모인 여자들에게 말씀을 전하고, 자주 장사 루디아가 마음을 열어 세례를 받습니다. 이어 점치는 여종에게서 귀신을 쫓아내자 주인들이 바울과 실라를 고발하여 매 맞고 옥에 갇힙니다(16:16–24).","한밤에 바울과 실라가 찬송할 때 지진이 나고 옥문이 열리며, 간수가 자결하려다 “내가 어떻게 하여야 구원을 얻으리이까”라고 묻고 온 집이 믿어 세례를 받습니다(16:25–34). 바울은 로마 시민임을 밝히고 공개 사과를 받습니다(16:35–39). 빌립보서는 이 교회에 보낸 편지입니다."],"read":[{"ref":"행 16:11","hash":"act-16:11","why":"루디아와 옥중의 지진."},{"ref":"빌 1:1","hash":"php-1:1","why":"빌립보 교회에 보낸 편지."},{"ref":"빌 4:15","hash":"php-4:15","why":"빌립보 교회의 후원."}]},"thessalonica":{"hook":"마게도냐 지방의 큰 항구 도시로, 바울이 세 안식일 동안 회당에서 강론한 곳입니다.","place":"에게 해 북쪽 마게도냐 해안에 있으며 에그나티아 대로가 도시를 지나갔습니다.","meaning":"알렉산드로스 대왕의 이복누이 이름에서 온 이름입니다.","paras":["사도행전 17:1–9에서 바울은 암비볼리와 아볼로니아를 지나 데살로니가에서 세 안식일 동안 회당에서 성경을 풀어 그리스도가 고난을 받고 살아나야 하심을 논증합니다. 유대인 일부와 경건한 헬라인, 귀부인들이 믿지만, 시기한 유대인들이 소동을 일으켜 야손의 집을 습격합니다.","그리하여 형제들은 밤에 바울과 실라를 베뢰아로 보냅니다(17:10). 바울은 그 뒤 데살로니가 교회에 편지(데살로니가전서)를 써서 우상을 버리고 살아 계신 하나님을 섬기게 된 이들을 칭찬합니다(살전 1:9)."],"read":[{"ref":"행 17:1","hash":"act-17:1","why":"데살로니가에서의 전도."},{"ref":"살전 1:9","hash":"1th-1:9","why":"우상에서 돌아선 교회."},{"ref":"빌 4:16","hash":"php-4:16","why":"데살로니가에서도 보내 준 도움."}]},"berea":{"hook":"마게도냐의 성읍으로, 사람들이 날마다 성경을 상고한 곳입니다.","place":"데살로니가 서남쪽 내륙에 있었습니다.","meaning":null,"paras":["데살로니가에서 쫓겨난 바울과 실라는 베뢰아의 유대인 회당에 들어갑니다. 사도행전 17:11은 이곳 사람들이 데살로니가 사람보다 “너그러워” 간절한 마음으로 말씀을 받고 “이것이 그러한가 하여 날마다 성경을 상고”했다고 칭찬합니다.","그러나 데살로니가의 유대인들이 따라와 무리를 선동하자 형제들은 바울을 바다 쪽으로 내보내고 실라와 디모데는 남습니다(17:13–14). 이 성의 소바더가 바울 일행에 있었다고 사도행전 20:4에 나옵니다."],"read":[{"ref":"행 17:10","hash":"act-17:10","why":"베뢰아에서."},{"ref":"행 17:11","hash":"act-17:11","why":"날마다 성경을 상고함."},{"ref":"행 20:4","hash":"act-20:4","why":"베뢰아 사람 소바더."}]},"athens":{"hook":"그리스 철학과 문화의 중심지로, 바울이 아레오바고에서 설교한 곳입니다.","place":"그리스 아티카 반도에 있으며 아크로폴리스와 장터(아고라)가 중심이었습니다.","meaning":"지혜와 전쟁의 여신 아테나의 이름에서 온 도시 이름입니다.","paras":["사도행전 17:16은 바울이 아덴에서 성에 우상이 가득한 것을 보고 격분하여 회당과 장터에서 날마다 만나는 사람들과 변론했다고 전합니다. 에피쿠로스 학파와 스토아 학파의 철학자들이 그를 아레오바고로 데려가 새 교훈을 설명해 달라고 합니다.","바울은 “알지 못하는 신에게”라고 새긴 제단을 단서로 천지를 지으신 하나님을 전하고, 그가 정하신 사람으로 심판하실 것과 부활을 말합니다(17:22–31). 어떤 이는 조롱했으나 아레오바고 관원 디오누시오와 다마리라는 여자가 믿습니다(17:32–34)."],"read":[{"ref":"행 17:16","hash":"act-17:16","why":"아덴의 우상."},{"ref":"행 17:22","hash":"act-17:22","why":"아레오바고 설교."},{"ref":"행 17:34","hash":"act-17:34","why":"믿은 사람들."}]},"corinth":{"hook":"그리스 남부의 항구 상업 도시로, 바울이 일 년 반을 머물며 교회를 세운 곳입니다.","place":"펠로폰네소스 반도와 본토를 잇는 좁은 땅 위에 있었고, 동쪽 겐그레아와 서쪽 레기온 두 항구를 가졌습니다.","meaning":null,"paras":["사도행전 18:1–18은 바울이 아덴에서 고린도로 가서 로마에서 쫓겨난 유대인 아굴라와 브리스길라를 만나 같은 천막 만드는 일을 하며 안식일마다 회당에서 강론한 일을 전합니다. 회당장 그리스보 일가를 비롯해 많은 고린도 사람이 믿고, 바울은 일 년 육 개월을 머뭅니다.","유대인들이 총독 갈리오 앞에 바울을 고발하지만 갈리오는 종교 문제라며 받아들이지 않습니다(18:12–17). 고린도전서와 후서는 이 도시의 교회에 보낸 편지로, 분열, 은사, 부활, 연보 같은 문제를 다룹니다."],"read":[{"ref":"행 18:1","hash":"act-18:1","why":"고린도 전도."},{"ref":"고전 1:2","hash":"1co-1:2","why":"고린도 교회에 보내는 편지."},{"ref":"행 18:12","hash":"act-18:12","why":"갈리오 앞에서."}]},"ephesus":{"hook":"소아시아 서쪽의 큰 항구 도시로, 바울이 두 해 넘게 머물며 사역한 곳입니다.","place":"에게 해 연안, 오늘날 튀르키예 셀주크 부근에 있었으며 아데미(아르테미스) 신전으로 유명했습니다.","meaning":null,"paras":["사도행전 19:1–20은 바울이 에베소에서 두란노 서원에서 두 해 동안 날마다 강론하여 아시아에 사는 유대인과 헬라인이 다 주의 말씀을 듣게 되었다고 전합니다. 마술 책을 불사른 일도 이때 일어납니다.","19:23–41에는 은장색 데메드리오가 아데미 신전 모형을 만드는 이들을 선동해 극장에 큰 소동이 인 이야기가 나옵니다. 에베소서와 요한계시록 2:1–7(에베소 교회에 보낸 편지)도 이 도시와 관련됩니다. 디모데는 에베소에 남아 교회를 돌보았다고 전해집니다(딤전 1:3)."],"read":[{"ref":"행 19:1","hash":"act-19:1","why":"에베소 사역."},{"ref":"행 19:23","hash":"act-19:23","why":"아데미 소동."},{"ref":"계 2:1","hash":"rev-2:1","why":"에베소 교회에 보낸 편지."}]},"miletus":{"hook":"에베소 남쪽의 항구로, 바울이 에베소 장로들에게 고별 설교를 한 곳입니다.","place":"소아시아 서쪽 해안, 에베소에서 남쪽으로 약 50km에 있었습니다.","meaning":null,"paras":["3차 선교여행에서 예루살렘으로 서둘러 가던 바울은 에베소에 들르지 않고 밀레도에서 사람을 보내 에베소 장로들을 부릅니다(행 20:15–17). 그는 자기가 어떻게 겸손과 눈물로 섬겼는지 말하고, 결박과 환난이 기다리고 있다고 알리며 양 떼를 잘 돌보고 이리를 경계하라고 당부합니다(20:18–31).","“주 예수께서 친히 말씀하신 바 받는 것보다 주는 것이 복이 있다 하신 말씀을 기억하여야 할지니라”는 말씀도 이 설교에 나옵니다(20:35). 이야기는 모두 무릎을 꿇고 기도한 뒤 바울을 끌어안고 울며 배에까지 배웅하는 장면으로 끝납니다(20:36–38)."],"read":[{"ref":"행 20:17","hash":"act-20:17","why":"장로들을 부름."},{"ref":"행 20:28","hash":"act-20:28","why":"교회를 돌보라는 당부."},{"ref":"딤후 4:20","hash":"2ti-4:20","why":"밀레도에 남은 드로비모."}]},"fair_havens":{"hook":"그레데 섬 남쪽 해안의 항구로, 바울이 항해의 위험을 경고한 곳입니다.","place":"그레데 섬 남쪽 해안에 있으며, 지금의 칼로이 리메네스(좋은 항구)로 보는 견해가 많습니다.","meaning":"“좋은 항구”라는 뜻의 이름으로 소개됩니다.","paras":["사도행전 27:8은 배가 그레데 남쪽 해안을 따라 겨우 “미항”이라는 곳에 이르렀다고 적습니다. 금식절(속죄일)이 지나 항해가 위험해지자 바울은 이대로 가면 하물과 배뿐 아니라 사람의 생명에도 손해가 있으리라고 말합니다(27:9–10).","그러나 백부장은 선장과 선주의 말을 더 믿었고, 미항은 겨울을 지내기에 불편하여 대다수가 뵈닉스에 가서 겨울을 나자고 의견을 모읍니다(27:11–12). 남풍이 순하게 불자 출항했으나 곧 “유라굴로”라는 광풍을 만납니다(27:13–14)."],"read":[{"ref":"행 27:8","hash":"act-27:8","why":"미항에 이름."},{"ref":"행 27:10","hash":"act-27:10","why":"바울의 경고."},{"ref":"행 27:14","hash":"act-27:14","why":"유라굴로 광풍."}]},"malta":{"hook":"지중해 중앙의 섬으로, 바울을 태운 배가 풍랑 끝에 닿은 곳입니다.","place":"시칠리아 남쪽 지중해에 있는 섬입니다(사도행전의 ‘멜리데’).","meaning":null,"paras":["사도행전 27:13–44는 열나흘 동안 표류한 배가 풍랑 속에서 부서지고, 모든 사람이 널조각과 헤엄으로 무사히 뭍에 오른 일을 전합니다. 바울은 앞서 천사가 “너는 가이사 앞에 서야 하겠고 … 너와 함께 타 사람들을 다 네게 주셨다”고 한 말씀을 전하며 사람들을 격려했습니다(27:23–24).","섬 사람들은 친절하게 맞이했고, 바울이 불 속에서 독사에게 물리고도 해를 입지 않자 신이라 여깁니다(28:1–6). 바울은 추장 보블리오의 아버지를 기도하고 안수하여 고치고, 섬의 다른 병자들도 고침을 받습니다(28:7–9). 바울 일행은 석 달을 머문 뒤 알렉산드리아 배로 다시 출항합니다(28:11)."],"read":[{"ref":"행 27:41","hash":"act-27:41","why":"배가 부서짐."},{"ref":"행 28:3","hash":"act-28:3","why":"독사 사건."},{"ref":"행 28:11","hash":"act-28:11","why":"석 달 후의 출항."}]},"puteoli":{"hook":"이탈리아 나폴리 만의 항구로, 바울이 로마로 가는 길에 이탈리아에서 처음 닿은 곳입니다.","place":"나폴리 서쪽 해안에 있었고, 알렉산드리아에서 오는 곡물선이 닿던 큰 항구였습니다.","meaning":null,"paras":["사도행전 28:13–14에서 배는 수라구사와 레기온을 거쳐 보디올에 이릅니다. 바울은 그곳에서 형제들을 만나 이레를 함께 머물라는 청을 받습니다. 이 구절은 이미 로마 제국의 남부에 신자들이 있었음을 보여 줍니다.","그 후 일행은 육로로 로마를 향하고, 로마의 형제들이 소식을 듣고 압비아 광장과 삼관까지 나와 바울을 맞이합니다(28:15). 바울은 이를 보고 하나님께 감사하며 담대해집니다."],"read":[{"ref":"행 28:13","hash":"act-28:13","why":"보디올에 이름."},{"ref":"행 28:15","hash":"act-28:15","why":"로마 형제들의 마중."}]},"rome":{"hook":"로마 제국의 수도로, 바울이 압송되어 이르러 두 해 동안 복음을 전한 곳입니다.","place":"이탈리아 중부 티베르 강가에 있었고, 사도행전의 마지막 장소입니다.","meaning":null,"paras":["로마서 1:7은 바울이 “로마에 있는 하나님의 사랑하시는 자”들에게 편지를 쓴다고 하며, 그 교회는 바울이 가기 전부터 있었습니다. 사도행전 28:14–31에서 바울은 죄수의 몸으로 로마에 이르고, 군인을 붙여 따로 셋집에 머물도록 허락받습니다.","그는 이 년 동안 자기 셋집에서 찾아오는 사람들을 맞이하여 “하나님 나라를 전파하며 주 예수 그리스도에 관한 것을 담대히 거침없이 가르치더라”(행 28:30–31)는 말로 사도행전이 끝납니다. 옥중서신(빌립보서·에베소서·골로새서·빌레몬서)은 로마 감금 중 기록되었다고 보는 견해가 많습니다."],"read":[{"ref":"롬 1:7","hash":"rom-1:7","why":"로마 교회에 보낸 편지."},{"ref":"행 28:16","hash":"act-28:16","why":"로마 도착."},{"ref":"빌 1:13","hash":"php-1:13","why":"결박이 로마 근위대에 알려짐."}]},"patmos":{"hook":"에게 해의 작은 섬으로, 요한이 계시를 받을 때 있던 곳입니다.","place":"소아시아 에베소 남서쪽 에게 해에 있는 도데카네스 제도의 작은 섬입니다.","meaning":null,"paras":["요한계시록 1:9는 요한이 “하나님의 말씀과 예수의 증거를 인하여 밧모라 하는 섬에” 있었다고 말합니다. 교회 전통은 이를 로마 제국의 박해 때 유배당한 것으로 이해하지만, 구절 자체는 이유를 그렇게 길게 설명하지 않습니다.","요한은 주의 날에 성령에 감동되어 큰 음성을 듣고 일곱 금 촛대 사이를 거니시는 인자 같은 이를 봅니다(1:10–20). 이 환상에 이어 에베소, 서머나, 버가모, 두아디라, 사데, 빌라델비아, 라오디게아 일곱 교회에 보내는 편지가 이어집니다(2–3장)."],"read":[{"ref":"계 1:9","hash":"rev-1:9","why":"밧모 섬의 요한."},{"ref":"계 1:12","hash":"rev-1:12","why":"일곱 촛대 사이의 인자."},{"ref":"계 2:1","hash":"rev-2:1","why":"일곱 교회에 보내는 편지."}]},"gilgal":{"hook":"여호수아가 요단을 건넌 뒤 첫 진을 친 곳이며, 사울이 왕으로 세워진 곳입니다.","place":"여리고 동쪽 요단 가까이로 전해지지만, 같은 이름의 장소가 여럿이고 후보지가 나뉘어 위치는 확정되지 않았습니다.","meaning":"“굴러 버림”(수 5:9의 말놀이)과 연결해 설명됩니다.","paras":["여호수아 4:19–20은 백성이 요단에서 올라와 여리고 동편 길갈에 진을 치고 요단에서 가져온 열두 돌을 세웠다고 전합니다. 5장에서는 이곳에서 사람들이 할례를 받고 유월절을 지키며, 하나님이 “오늘날 내가 애굽의 수치를 너희에게서 떠나가게 하였다”고 하시자 그 이름이 길갈이 됩니다(5:2–10).","사무엘 시대에 길갈은 사무엘이 순회하던 곳이며 사울이 왕으로 세워진 곳입니다(삼상 11:14–15). 사울은 이곳에서 기다리지 못하고 번제를 드려 책망받고(13:8–14), 사무엘은 길갈에서 아각을 칩니다(15:33). 후에 호세아와 아모스는 길갈의 제사를 책망합니다(호 4:15; 암 4:4)."],"read":[{"ref":"수 4:19","hash":"jos-4:19","why":"길갈에 진을 침."},{"ref":"수 5:2","hash":"jos-5:2","why":"할례와 유월절."},{"ref":"삼상 11:14","hash":"1sa-11:14","why":"사울의 즉위."}]},"ai":{"hook":"여호수아의 정복 이야기에서 여리고 다음에 공략한 성으로, 아간의 범죄와 승리의 이야기가 있는 곳입니다.","place":"벧엘 가까운 곳으로 보지만, 엣텔 등 후보지가 나뉘어 위치는 논란이 있습니다.","meaning":"“폐허 더미”라는 뜻으로 풀이됩니다.","paras":["여호수아 7장은 아이를 칠 때 이스라엘이 패하여 서른여섯 명 가량이 죽고, 그 이유가 아간이 바친 물건을 가져간 죄 때문이었음이 밝혀지는 이야기를 전합니다. 아간과 그의 소유가 아골 골짜기에서 처리됩니다.","8장에서는 여호수아가 복병 계획으로 아이 성을 무너뜨립니다. 일부 군사를 성 뒤에 매복시키고 주력 부대가 거짓으로 물러나 성안 사람들을 끌어낸 뒤 성을 불태웁니다. 창세기 12:8에서 아브람은 벧엘 동편 산에 장막을 치는데 그곳이 벧엘과 아이 사이였습니다."],"read":[{"ref":"수 7:1","hash":"jos-7:1","why":"아간의 범죄."},{"ref":"수 8:1","hash":"jos-8:1","why":"아이 성의 함락."},{"ref":"창 12:8","hash":"gen-12:8","why":"아브람의 장막 위치."}]},"gibeon":{"hook":"이스라엘과 평화 조약을 맺은 히위 족속의 성읍으로, 솔로몬이 일천 번제를 드린 곳입니다.","place":"예루살렘 북서쪽 약 10km의 엘집에 해당하는 것으로 보는 견해가 많습니다.","meaning":null,"paras":["여호수아 9장은 기브온 사람들이 낡은 자루와 곰팡이 핀 떡으로 먼 나라에서 온 것처럼 꾸며 이스라엘과 조약을 맺고, 속임수가 드러난 뒤에도 약속 때문에 이스라엘이 그들을 살리되 나무 패고 물 긷는 종으로 삼은 일을 전합니다. 10장에서 기브온을 치려는 가나안 연합군을 여호수아가 구원하는데, 이때 해와 달이 멈춘 이야기가 이어집니다.","열왕기상 3:4–5에서 솔로몬이 기브온 산당에서 일천 번제를 드리자 하나님이 꿈에 나타나 무엇이든 구하라고 하시고 솔로몬은 지혜로운 마음을 구합니다. 사무엘 시대의 장군 아브넬과 요압이 기브온 못가에서 맞서기도 합니다(삼하 2:12–17)."],"read":[{"ref":"수 9:3","hash":"jos-9:3","why":"기브온의 속임수."},{"ref":"수 10:12","hash":"jos-10:12","why":"해야 멈추라."},{"ref":"왕상 3:4","hash":"1ki-3:4","why":"솔로몬의 일천 번제."}]},"shiloh":{"hook":"법궤와 회막이 있던 이스라엘의 옛 예배 중심지로, 사무엘이 자란 곳입니다.","place":"에브라임 산지 벧엘 북쪽 세겜 남쪽에 있었습니다(삿 21:19). 오늘의 텔 세일룬으로 봅니다.","meaning":null,"paras":["여호수아 18:1에서 온 회중이 실로에 모여 회막을 세우고, 남은 땅을 제비 뽑아 나눕니다. 사사 시대에 법궤가 실로에 있었고, 엘리 제사장과 한나 이야기가 나옵니다. 한나가 이곳에서 아들을 구하는 기도를 드리고 사무엘을 낳아 하나님께 드립니다(삼상 1장).","삼상 4장에서 이스라엘이 블레셋과 싸우다 법궤를 들고 나가지만 법궤를 빼앗기고 엘리와 두 아들이 죽습니다. 시편 78:60은 하나님이 실로의 장막을 떠나셨다고 노래하고, 예레미야 7:12–14는 성전을 믿고 악을 행하는 이들에게 “실로에 행한 것같이 이 성전에 행하리라”고 경고합니다."],"read":[{"ref":"수 18:1","hash":"jos-18:1","why":"실로에 회막을 세움."},{"ref":"삼상 1:3","hash":"1sa-1:3","why":"한나의 기도와 사무엘."},{"ref":"렘 7:12","hash":"jer-7:12","why":"실로의 교훈."}]}};
